insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('emotional-intelligence', 'Emotional Intelligence', 'Self-awareness, self-regulation, empathy, social awareness and relationship management, based on EQ-i 2.0 and MSCEIT frameworks.', 'Emotional Intelligence measures how you perceive, use, understand, and manage emotions — in yourself and others — across 9 EQ facets drawn from the EQ-i 2.0 and MSCEIT frameworks: Perceiving Emotions, Using Emotions, Understanding Emotions, Managing Emotions, Self-Perception, Self-Expression, Interpersonal Skills, Decision Making, and Stress Management.', 'heart-handshake', (select id from assessment_categories where key = 'emotional'), ('standard_questionnaire')::assessment_engine_type, ('medium')::assessment_difficulty, 15, 40, false, ('free')::assessment_access, ('published')::assessment_status)
